// Paste into Extensions → Apps Script, then Deploy → New deployment → Web app
// (Execute as: Me, Who has access: Anyone). Copy the /exec link into the dashboard.
const SHEET_NAME = 'EOD Reports';
const HEADERS = ['Date', 'Submitted at', 'What I accomplished', "What didn't get done & why",
  "Tomorrow's #1 priority", 'EOD checklist', 'Checklist done', 'Tasks done', 'Routine done',
  'Meetings done', 'Leads contacted', 'Day reviewed'];

function doPost(e) {
  try {
    const d = JSON.parse(e.postData.contents);
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const sh = ss.getSheetByName(SHEET_NAME) || ss.insertSheet(SHEET_NAME);
    if (sh.getLastRow() === 0) {
      sh.appendRow(HEADERS);
      sh.setFrozenRows(1);
      sh.getRange(1, 1, 1, HEADERS.length).setFontWeight('bold');
      sh.getRange('A:A').setNumberFormat('@');
    }
    const key = d.test ? 'TEST' : String(d.date);
    const row = [key, new Date(d.submittedAt), d.accomplished, d.notDone, d.tomorrowPriority,
      d.checklist, d.checklistDone, d.tasksDone, d.routineDone, d.meetingsDone,
      d.leadsContacted, d.reviewed ? 'Yes' : 'No'];
    const last = sh.getLastRow();
    const dates = last > 1 ? sh.getRange(2, 1, last - 1, 1).getDisplayValues().map(r => r[0]) : [];
    const i = dates.indexOf(key);
    if (i >= 0) sh.getRange(i + 2, 1, 1, row.length).setValues([row]);
    else sh.appendRow(row);
    return json({ ok: true });
  } catch (err) {
    return json({ ok: false, error: String(err) });
  }
}

function doGet() { return json({ ok: true, message: 'EOD report endpoint is live.' }); }

function json(o) {
  return ContentService.createTextOutput(JSON.stringify(o)).setMimeType(ContentService.MimeType.JSON);
}
